// GetManyByIDs retrieves multiple Order records by their IDs in a single query
func (r *OrderRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Order, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Order{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "title", "total_cents", "payments_due", "payments_authorized", "payments_captured", "payments_refunded", "payments_outstanding", "payments_overpaid", "payments_currency", "payments_state", "status", "status_entered_at", "_version" FROM "order" WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Order, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Order{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempPaymentsDue *types.GenericInt64
		var tempPaymentsAuthorized *types.GenericInt64
		var tempPaymentsCaptured *types.GenericInt64
		var tempPaymentsRefunded *types.GenericInt64
		var tempPaymentsOutstanding *types.GenericInt64
		var tempPaymentsOverpaid *types.GenericInt64
		var tempPaymentsCurrency sql.NullString
		var tempPaymentsState sql.NullString
		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Title,

			&entity.TotalCents,

			&tempPaymentsDue,

			&tempPaymentsAuthorized,

			&tempPaymentsCaptured,

			&tempPaymentsRefunded,

			&tempPaymentsOutstanding,

			&tempPaymentsOverpaid,

			&tempPaymentsCurrency,

			&tempPaymentsState,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempPaymentsDue != nil {
			entity.PaymentsDue = tempPaymentsDue
		}
		if tempPaymentsAuthorized != nil {
			entity.PaymentsAuthorized = tempPaymentsAuthorized
		}
		if tempPaymentsCaptured != nil {
			entity.PaymentsCaptured = tempPaymentsCaptured
		}
		if tempPaymentsRefunded != nil {
			entity.PaymentsRefunded = tempPaymentsRefunded
		}
		if tempPaymentsOutstanding != nil {
			entity.PaymentsOutstanding = tempPaymentsOutstanding
		}
		if tempPaymentsOverpaid != nil {
			entity.PaymentsOverpaid = tempPaymentsOverpaid
		}
		if tempPaymentsCurrency.Valid {
			entity.PaymentsCurrency = tempPaymentsCurrency.String
		}
		if tempPaymentsState.Valid {
			entity.PaymentsState = tempPaymentsState.String
		}
		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values

		entityID, ok := orderUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

