// FindPage reads a page of the Order rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *OrderRepository) FindPage(ctx context.Context, filter *OrderFilter, opts *OrderPageOptions) (*OrderPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Order rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = OrderSortById
	}
	column, ok := orderSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Order sorts by id, title, totalCents, paymentsDue, paymentsAuthorized, paymentsCaptured, paymentsRefunded, paymentsOutstanding, paymentsOverpaid, paymentsCurrency, paymentsState, status and statusEnteredAt, not %q", string(field))
	}
	byKey := field == OrderSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := orderFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, OrderAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "order")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		afterKey := fmt.Sprintf(`"order".id %s %s`, comparison, placeholder)
		if byKey {
			conditions = append(conditions, afterKey)
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			after := fmt.Sprintf(`(%s, "order".id) %s ((SELECT %s FROM "order" AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder)
			if column.nulls {
				// Nulls come last in either direction (D112): after a
				// null, the nulls past the key; after a value, every null
				// and the values past it.
				after = fmt.Sprintf(`CASE (SELECT %s IS NULL FROM "order" AS page_key WHERE page_key.id = %s) WHEN TRUE THEN %s IS NULL AND %s WHEN FALSE THEN (%s IS NULL OR %s) END`,
					column.key, placeholder, column.sql, afterKey, column.sql, after)
			}
			conditions = append(conditions, after)
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if column.nulls {
		orderByClause = fmt.Sprintf(" ORDER BY %s %s NULLS LAST", column.sql, direction)
	}
	if !byKey {
		orderByClause += fmt.Sprintf(`, "order".id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM "order"%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &OrderPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = orderPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *OrderRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM "order" WHERE "order".id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Order row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Order row through the behaviors' core (D103), in a
// transaction: each behavior's create initializes the fields it owns, and the
// row is read back. A refusal of the core's is returned as the *rules.Refusal
// it is.
func (r *OrderRepository) CreateOne(ctx context.Context, input *OrderCreate) (*types.Order, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Order, error) {
		return (&OrderRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// orderUniqueKeys are the conflict targets of Order's unique keys, and
// the assignment of the update an upsert that sets nothing names, which its
// WHERE FALSE never runs (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert reads back when it leaves them as they
// were, empty for a key over an expression, and that key's read of the row
// that holds one input's value of it, empty for a key over columns; and the
// key's columns as a batch insert's cells name them (D89).
var orderUniqueKeys = map[OrderUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	OrderUniqueById: {`(id)`, `id = "order".id`, `SELECT "id", "title", "total_cents", "payments_due", "payments_authorized", "payments_captured", "payments_refunded", "payments_outstanding", "payments_overpaid", "payments_currency", "payments_state", "status", "status_entered_at", "_version" FROM "order" WHERE (id) IN (%s)`, ``, []string{`id`}},
}

// orderKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func orderKeyOf(on OrderUniqueKey, row *types.Order) (string, bool) {
	switch on {
	case OrderUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *OrderRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Order, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *OrderRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Order, error) {
	result := &types.Order{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempPaymentsDue *types.GenericInt64
	var tempPaymentsAuthorized *types.GenericInt64
	var tempPaymentsCaptured *types.GenericInt64
	var tempPaymentsRefunded *types.GenericInt64
	var tempPaymentsOutstanding *types.GenericInt64
	var tempPaymentsOverpaid *types.GenericInt64
	var tempPaymentsCurrency sql.NullString
	var tempPaymentsState sql.NullString
	var tempStatusEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&result.Title,

		&result.TotalCents,

		&tempPaymentsDue,

		&tempPaymentsAuthorized,

		&tempPaymentsCaptured,

		&tempPaymentsRefunded,

		&tempPaymentsOutstanding,

		&tempPaymentsOverpaid,

		&tempPaymentsCurrency,

		&tempPaymentsState,

		&result.Status,

		&tempStatusEnteredAt,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempPaymentsDue != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentsDue = tempPaymentsDue
	}
	if tempPaymentsAuthorized != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentsAuthorized = tempPaymentsAuthorized
	}
	if tempPaymentsCaptured != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentsCaptured = tempPaymentsCaptured
	}
	if tempPaymentsRefunded != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentsRefunded = tempPaymentsRefunded
	}
	if tempPaymentsOutstanding != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentsOutstanding = tempPaymentsOutstanding
	}
	if tempPaymentsOverpaid != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PaymentsOverpaid = tempPaymentsOverpaid
	}
	if tempPaymentsCurrency.Valid {
		result.PaymentsCurrency = tempPaymentsCurrency.String
	}
	if tempPaymentsState.Valid {
		result.PaymentsState = tempPaymentsState.String
	}
	if tempStatusEnteredAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.StatusEnteredAt = tempStatusEnteredAt
	}

	// Set relationship IDs from scanned FK values

	return result, nil
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, when the update sets no field or
// only if changed, and the second statement of an encrypted field.
func (r *OrderRepository) upsertRow(ctx context.Context, input *types.Order, on OrderUniqueKey, update *OrderUpdate, onlyIfChanged bool) (*UpsertResult[*types.Order], error) {
	key := orderUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := orderUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: title
	fields = append(fields, `title`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Title)
	// Required field: totalCents
	fields = append(fields, `total_cents`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.TotalCents)
	// Optional field: paymentsDue - only add if set
	{
		if input.PaymentsDue != nil {
			fields = append(fields, `payments_due`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PaymentsDue)
		}
	}
	// Optional field: paymentsAuthorized - only add if set
	{
		if input.PaymentsAuthorized != nil {
			fields = append(fields, `payments_authorized`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PaymentsAuthorized)
		}
	}
	// Optional field: paymentsCaptured - only add if set
	{
		if input.PaymentsCaptured != nil {
			fields = append(fields, `payments_captured`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PaymentsCaptured)
		}
	}
	// Optional field: paymentsRefunded - only add if set
	{
		if input.PaymentsRefunded != nil {
			fields = append(fields, `payments_refunded`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PaymentsRefunded)
		}
	}
	// Optional field: paymentsOutstanding - only add if set
	{
		if input.PaymentsOutstanding != nil {
			fields = append(fields, `payments_outstanding`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PaymentsOutstanding)
		}
	}
	// Optional field: paymentsOverpaid - only add if set
	{
		if input.PaymentsOverpaid != nil {
			fields = append(fields, `payments_overpaid`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PaymentsOverpaid)
		}
	}
	// Optional field: paymentsCurrency - only add if set
	{
		if !reflect.ValueOf(input.PaymentsCurrency).IsZero() {
			fields = append(fields, `payments_currency`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.PaymentsCurrency)
		}
	}
	// Optional field: paymentsState - only add if set
	{
		if !reflect.ValueOf(input.PaymentsState).IsZero() {
			fields = append(fields, `payments_state`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.PaymentsState)
		}
	}
	// Required field: status
	fields = append(fields, `status`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Status)
	// Optional field: statusEnteredAt - only add if set
	{
		if input.StatusEnteredAt != nil {
			fields = append(fields, `status_entered_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.StatusEnteredAt))
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Title != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`title = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `"order".title`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Title)
	}
	if update.TotalCents != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`total_cents = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `"order".total_cents`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.TotalCents)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field compares none, so its WHERE is FALSE:
		// it leaves the row as it is, its version, stamps and history all,
		// and reads it back below.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO "order" (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "title", "total_cents", "payments_due", "payments_authorized", "payments_captured", "payments_refunded", "payments_outstanding", "payments_overpaid", "payments_currency", "payments_state", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || assigned == 0),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Order]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Order]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged && assigned > 0:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with, which the update sets no field of
		// or which already held the update's values, read back by its key:
		// a soft-deleted one is ErrNotFound.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Order row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.heldOfKey(ctx, on, keyValues, input)
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Order]{Row: found, Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// when update names no field or only if changed, and the second statement
// of each encrypted field.
func (r *OrderRepository) upsertBatches(ctx context.Context, inputs []*types.Order, on OrderUniqueKey, update OrderFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Order], error) {
	key := orderUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Title {
		setClauses = append(setClauses, `title = EXCLUDED.title`)
		compareCurrent = append(compareCurrent, `"order".title`)
		compareNext = append(compareNext, `EXCLUDED.title`)
	}
	if update.TotalCents {
		setClauses = append(setClauses, `total_cents = EXCLUDED.total_cents`)
		compareCurrent = append(compareCurrent, `"order".total_cents`)
		compareNext = append(compareNext, `EXCLUDED.total_cents`)
	}

	results := make([]UpsertResult[*types.Order], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := orderUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: title
			{
				cell := batchInsertCell{column: `title`, set: true}
				cell.value = input.Title
				row = append(row, cell)
			}
			// Required field: totalCents
			{
				cell := batchInsertCell{column: `total_cents`, set: true}
				cell.value = input.TotalCents
				row = append(row, cell)
			}
			// Optional field: paymentsDue
			{
				cell := batchInsertCell{column: `payments_due`}
				if input.PaymentsDue != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PaymentsDue
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsAuthorized
			{
				cell := batchInsertCell{column: `payments_authorized`}
				if input.PaymentsAuthorized != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PaymentsAuthorized
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsCaptured
			{
				cell := batchInsertCell{column: `payments_captured`}
				if input.PaymentsCaptured != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PaymentsCaptured
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsRefunded
			{
				cell := batchInsertCell{column: `payments_refunded`}
				if input.PaymentsRefunded != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PaymentsRefunded
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsOutstanding
			{
				cell := batchInsertCell{column: `payments_outstanding`}
				if input.PaymentsOutstanding != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PaymentsOutstanding
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsOverpaid
			{
				cell := batchInsertCell{column: `payments_overpaid`}
				if input.PaymentsOverpaid != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PaymentsOverpaid
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsCurrency
			{
				cell := batchInsertCell{column: `payments_currency`}
				if !reflect.ValueOf(input.PaymentsCurrency).IsZero() {
					cell.value = input.PaymentsCurrency
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: paymentsState
			{
				cell := batchInsertCell{column: `payments_state`}
				if !reflect.ValueOf(input.PaymentsState).IsZero() {
					cell.value = input.PaymentsState
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: status
			{
				cell := batchInsertCell{column: `status`, set: true}
				cell.value = input.Status
				row = append(row, cell)
			}
			// Optional field: statusEnteredAt
			{
				cell := batchInsertCell{column: `status_entered_at`}
				if input.StatusEnteredAt != nil {
					cell.value = time.Time(*input.StatusEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field compares none, so its WHERE is
			// FALSE: it leaves each row as it is, its version, stamps and
			// history all, and reads it back below.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO "order" (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "title", "total_cents", "payments_due", "payments_authorized", "payments_captured", "payments_refunded", "payments_outstanding", "payments_overpaid", "payments_currency", "payments_state", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || len(setClauses) == 0),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = orderKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Order], len(prepared))
		for n, row := range returned {
			text, ok := orderKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Order wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Order]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, when update
		// names no field or only if changed, which it reads back by its key,
		// or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged && len(setClauses) > 0 {
				return nil, fmt.Errorf("the Order row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Order, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Order row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Order]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *OrderRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Order, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Order
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert left as they were, as one whose
// update sets no field or one only if changed does (D89). A key no live
// row holds is ErrNotFound.
func (r *OrderRepository) rowsOfKeys(ctx context.Context, on OrderUniqueKey, keys [][]any, inputs []*types.Order) ([]*types.Order, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(orderUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Order{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := orderKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Order, len(inputs))
	for i, input := range inputs {
		text, _ := orderKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Order row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// heldOfKey reads the row that holds input's value of the unique key on,
// keyValues the values of the key's columns its insert binds, which an
// upsert left as it was: by rowsOfKeys, or, for a key over an expression,
// whose columns read no row, by the expression's value over keyValues
// (sqlutil.UniqueKey.Held, D105). A key no live row holds is ErrNotFound.
func (r *OrderRepository) heldOfKey(ctx context.Context, on OrderUniqueKey, keyValues []any, input *types.Order) (*types.Order, error) {
	query := orderUniqueKeys[on].held
	if query == "" {
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Order{input})
		if err != nil {
			return nil, err
		}
		return found[0], nil
	}
	var read pgx.Row
	if r.tx != nil {
		read = r.tx.QueryRow(ctx, query, keyValues...)
	} else {
		read = r.db.pool.QueryRow(ctx, query, keyValues...)
	}
	row, err := r.scanReturned(read, nil)
	if err == pgx.ErrNoRows {
		return nil, fmt.Errorf("the Order row that holds the key %s is deleted: %w", string(on), ErrNotFound)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the row the upsert left: %w", err)
	}
	return row, nil
}

// CreateMany inserts multiple Order rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *OrderRepository) CreateMany(ctx context.Context, inputs []*OrderCreate) ([]*types.Order, error) {
	if len(inputs) == 0 {
		return []*types.Order{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Order, error) {
		repo := &OrderRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Order, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Order row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *OrderRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *OrderUpdate) (*types.Order, error) {
	if update == nil {
		update = &OrderUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Order, error) {
		repo := &OrderRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Order", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return nil, behaviorNotFound(err, "Order", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Order records matching the filter
func (r *OrderRepository) UpdateMany(ctx context.Context, filter *OrderFilter, update *OrderUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Title != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`title = $%d`, paramNum))
		values = append(values, *update.Title)
	}
	if update.TotalCents != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`total_cents = $%d`, paramNum))
		values = append(values, *update.TotalCents)
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE "order" SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Order row by ID through the
// behaviors' core (D103), in a transaction. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *OrderRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Order", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Order", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Order records matching the filter
func (r *OrderRepository) DeleteMany(ctx context.Context, filter *OrderFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM "order"%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
